Structure:

{
  "type":"mol",
  "smiles": target,
  "children":[
    {
      "type":"reaction",
      "template_id":"R001", // sulfonylation
      "children":[
        {"type":"mol","smiles":"ClS(=O)(=O)c1ccc(F)cc1"},
        {"type":"mol","smiles":"Nc1ccc(N2CCN(C(=O)OC(C)(C)C)CC2)cc2C(CCC3(CCC3)O3)=C2","children":[
          {
            "type":"reaction",
